const $=id=>document.getElementById(id),{tools,detect,execute}=FlowCore;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let steps=read('flowkit.steps',['pretty','mask']).filter(x=>tools[x]), saved=read('flowkit.saved',[]),trace=[],result='',busy=false;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('瀏覽器儲存空間無法使用');}}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3000);}
function invalidate(){trace=[];result='';$('output').value='';$('outputCount').textContent='0 字元';$('resultTag').textContent='等待執行';$('status').textContent='資料或流程已更新，請重新執行。';$('status').classList.remove('error');}
function drawSteps(){const root=$('steps');root.replaceChildren();steps.forEach((id,i)=>{const div=document.createElement('div');div.className='step';const num=document.createElement('span');num.className='num';num.textContent=String(i+1).padStart(2,'0');div.append(num);for(const [label,title,fn]of [[tools[id].name,'查看此步結果',()=>{if(trace[i]){$('output').value=trace[i].value;$('resultTag').textContent='第 '+(i+1)+' 步';$('outputCount').textContent=trace[i].value.length+' 字元';}else toast('先執行流程，即可查看此步結果');}],['‹','向前移動',()=>move(i,-1)],['›','向後移動',()=>move(i,1)],['×','移除步驟',()=>{steps.splice(i,1);changed();}]]){const b=document.createElement('button');b.textContent=label;b.title=title;b.setAttribute('aria-label',title+' '+tools[id].name);if(label===tools[id].name)b.className='name';b.onclick=fn;div.append(b);}root.append(div);});persist('flowkit.steps',steps);}
function changed(){invalidate();drawSteps();}function move(i,d){if(i+d<0||i+d>=steps.length)return;[steps[i],steps[i+d]]=[steps[i+d],steps[i]];changed();}
function renderTools(){const term=$('search').value.toLowerCase();$('tools').replaceChildren();Object.entries(tools).filter(([id,t])=>(t.name+id+t.category).toLowerCase().includes(term)).forEach(([id,t])=>{const b=document.createElement('button');b.className='tool';b.title=t.description;const icon=document.createElement('span');icon.textContent=t.icon;b.append(icon,document.createTextNode(t.name));const plus=document.createElement('b');plus.textContent='＋';b.append(plus);b.onclick=()=>{steps.push(id);changed();};$('tools').append(b);});}
const example=JSON.stringify({project:'FlowKit',user:{name:'小林',email:'lin@example.com',api_key:'demo-key-not-real'},features:['流程串接','本機處理'],ready:true});
const templates={safe:{steps:['pretty','mask'],input:example},decode:{steps:['decode','pretty'],input:tools.encode.run(example)},clean:{steps:['trim','unique','sort'],input:'  設計介面  \n撰寫文件\n設計介面\n\n測試流程\n  撰寫文件'}};
function updateInput(){invalidate();$('inputCount').textContent=$('input').value.length+' 字元';$('detected').textContent=detect($('input').value).label;if($('remember').checked)persist('flowkit.input',$('input').value);}
document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{const t=templates[b.dataset.template];steps=[...t.steps];$('input').value=t.input;updateInput();drawSteps();toast('範本已載入，點擊執行流程');});
function drawSaved(){$('saved').replaceChildren();saved.forEach((s,i)=>{const box=document.createElement('div'),load=document.createElement('button'),del=document.createElement('button');load.textContent='◇ '+s.name;load.title=s.steps.map(x=>tools[x]?.name||x).join(' → ');load.onclick=()=>{steps=s.steps.filter(x=>tools[x]);changed();toast('已載入流程');};del.textContent='×';del.setAttribute('aria-label','刪除 '+s.name);del.onclick=()=>{saved.splice(i,1);persist('flowkit.saved',saved);drawSaved();};box.append(load,del);$('saved').append(box);});}
$('save').onclick=()=>{if(!steps.length)return toast('請先加入工具');const name=prompt('為流程命名',steps.map(x=>tools[x].name).join(' → '));if(!name?.trim())return;saved.push({name:name.trim().slice(0,100),steps:[...steps]});persist('flowkit.saved',saved);drawSaved();toast('流程已儲存在此裝置');};
$('run').onclick=async()=>{if(busy)return;if(!steps.length)return toast('請先加入至少一個工具');busy=true;$('run').disabled=true;$('status').classList.remove('error');const snapshot=$('input').value,sequence=[...steps],start=performance.now();invalidate();try{const out=await execute(snapshot,sequence);if(snapshot!==$('input').value||JSON.stringify(sequence)!==JSON.stringify(steps))return toast('資料已變更，請重新執行');result=out.value;trace=out.trace;$('output').value=result;$('outputCount').textContent=result.length+' 字元';$('resultTag').textContent='完成';$('status').textContent=steps.length+' 步完成 · '+Math.max(1,Math.round(performance.now()-start))+' ms';}catch(e){$('status').textContent=e.message;$('status').classList.add('error');$('resultTag').textContent='執行失敗';}finally{busy=false;$('run').disabled=false;}};
$('input').oninput=updateInput;$('search').oninput=renderTools;$('detect').onclick=()=>{steps.push(detect($('input').value).tool);changed();};$('reset').onclick=()=>{steps=[];changed();};$('example').onclick=()=>{$('input').value=example;updateInput();};$('remember').checked=read('flowkit.remember',false);$('input').value=$('remember').checked?read('flowkit.input',''):example;
$('remember').onchange=()=>{persist('flowkit.remember',$('remember').checked);if($('remember').checked)persist('flowkit.input',$('input').value);else try{localStorage.removeItem('flowkit.input');}catch{}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);toast('結果已複製');}catch{toast('無法存取剪貼簿，請選取結果手動複製');}};
$('download').onclick=()=>{const text=$('output').value;let json=false;try{JSON.parse(text);json=true;}catch{}const u=URL.createObjectURL(new Blob([text],{type:json?'application/json':'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='flowkit-result.'+(json?'json':'txt');a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('請選擇小於 5 MB 的文字檔');e.target.value='';return;}try{$('input').value=await f.text();updateInput();toast('檔案已匯入');}catch{toast('無法讀取檔案');}e.target.value='';};
$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('templatesNav').onclick=()=>$('templates').scrollIntoView({behavior:'smooth'});$('workspace').onclick=()=>document.querySelector('.workbench').scrollIntoView({behavior:'smooth'});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('run').click();}});renderTools();drawSteps();drawSaved();updateInput();
